dataSet.query:
ВЫБРАТЬ "Остаточная нагрузка" КАК Группировка, 1 КАК Порядок ПОМЕСТИТЬ ВТ_Группировки
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ "Не распределено", 2
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), 3
ОБЪЕДИНИТЬ
ВЫБРАТЬ НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 1), ДЕНЬ), 4
ОБЪЕДИНИТЬ
ВЫБРАТЬ НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 2), ДЕНЬ), 5
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ "Будущие", 6 ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Склады.Ссылка КАК Склад ПОМЕСТИТЬ ВТ_Склады ИЗ Справочник.Склады КАК Склады ГДЕ (Склады.Код = "000000004" ИЛИ Склады.Код = "000000001" ИЛИ Склады.Код = "000000017") ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ 1 КАК КоличествоПотолков, ЗаказНаПроизводство.ПродукцияНоменклатураКоличество КАК КоличествоМ2Потолков, ВЫБОР КОГДА ДЕНЬ(ЗаказНаПроизводство.ОжидаемаяДатаОтгрузки) = ДЕНЬ(&ТекущаяДата) ТОГДА НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ) КОГДА ДЕНЬ(ЗаказНаПроизводство.ОжидаемаяДатаОтгрузки) = ДЕНЬ(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 1)) ТОГДА НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 1), ДЕНЬ) КОГДА ДЕНЬ(ЗаказНаПроизводство.ОжидаемаяДатаОтгрузки) = ДЕНЬ(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 2)) ТОГДА НАЧАЛОПЕРИОДА(ДОБАВИТЬКДАТЕ(&ТекущаяДата, ДЕНЬ, 2), ДЕНЬ) КОГДА ДЕНЬ(ЗаказНаПроизводство.ОжидаемаяДатаОтгрузки) < ДЕНЬ(&ТекущаяДата) ТОГДА НАЧАЛОПЕРИОДА(ЗаказНаПроизводство.ОжидаемаяДатаОтгрузки, ДЕНЬ) ИНАЧЕ "Не в диапазоне дат" КОНЕЦ КАК День, ВЫБОР КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 0 ТОГДА "Нераспределенно" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 1 ТОГДА "01 - 02" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 2 ТОГДА "02 - 03" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 3 ТОГДА "03 - 04" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 4 ТОГДА "04 - 05" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 5 ТОГДА "05 - 06" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 6 ТОГДА "06 - 07" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 7 ТОГДА "07 - 08" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 8 ТОГДА "08 - 09" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 9 ТОГДА "09 - 10" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 10 ТОГДА "10 - 11" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 11 ТОГДА "11 - 12" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 12 ТОГДА "12 - 13" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 13 ТОГДА "13 - 14" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 14 ТОГДА "14 - 15" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 15 ТОГДА "15 - 16" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 16 ТОГДА "16 - 17" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 17 ТОГДА "17 - 18" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 18 ТОГДА "18 - 19" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 19 ТОГДА "19 - 20" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 20 ТОГДА "20 - 21" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 21 ТОГДА "21 - 22" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 22 ТОГДА "22 - 23" КОГДА ЧАС(ЕСТЬNULL(ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки, ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0))) = 23 ТОГДА "23 - 24" ИНАЧЕ "Нераспределенно" КОНЕЦ КАК Период, ЗаказНаПроизводство.Ссылка КАК ЗаказНаПроизовдство, ЗаказНаПроизводство.Склад КАК Склад, ЗаказНаПроизводство.ОжидаемоеВремяОтгрузки КАК ОжидаемоеВремяОтгрузки ПОМЕСТИТЬ ВТ_ЗаказыНаПроизводство ИЗ Документ.ЗаказНаПроизводство КАК ЗаказНаПроизводство ГДЕ (ЗаказНаПроизводство.ПродукцияНоменклатура.ВидНоменклатуры = ЗНАЧЕНИЕ(Справочник.ВидыНоменклатуры.Потолок) ИЛИ ЗаказНаПроизводство.ПродукцияНоменклатура.ВидНоменклатуры = ЗНАЧЕНИЕ(Справочник.ВидыНоменклатуры.Отрез)) И ЗаказНаПроизводство.ТекущийСтатус = ЗНАЧЕНИЕ(Справочник.СтатусыЗаказовНаПроизводство.ВПроизводстве) И ЗаказНаПроизводство.Склад <> ЗНАЧЕНИЕ(Справочник.Склады.ПустаяСсылка) И ЗаказНаПроизводство.Проведен И НЕ ЗаказНаПроизводство.ПометкаУдаления {ГДЕ ЗаказНаПроизводство.Склад.*} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ "Остаточная нагрузка" КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_ОстаточнаяНагрузка ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.День < НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ "Не распределено" КАК Группировка, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_НеРаспределено ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство.ОжидаемоеВремяОтгрузки = ДАТАВРЕМЯ(1, 1, 1, 0, 0, 0) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ) КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_Сегодня ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.День = НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), ДЕНЬ, 1) КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_Завтра ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.День = ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), ДЕНЬ, 1) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), ДЕНЬ, 2) КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_Послезавтра ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.День = ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), ДЕНЬ, 2) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ "Будущие" КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_ЗаказыНаПроизводство.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ЗаказыНаПроизводство.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_Будущие ИЗ ВТ_Склады КАК ВТ_Склады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ЗаказыНаПроизводство КАК ВТ_ЗаказыНаПроизводство ПО ВТ_Склады.Склад = ВТ_ЗаказыНаПроизводство.Склад ГДЕ ВТ_ЗаказыНаПроизводство.День > ДОБАВИТЬКДАТЕ(НАЧАЛОПЕРИОДА(&ТекущаяДата, ДЕНЬ), ДЕНЬ, 2) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_Группировки.Группировка КАК Группировка, ВТ_Склады.Склад КАК Склад, ВТ_Группировки.Порядок КАК Порядок ПОМЕСТИТЬ ВТ_ГруппировкиИСклады ИЗ ВТ_Группировки КАК ВТ_Группировки, ВТ_Склады КАК ВТ_Склады ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ОстаточнаяНагрузка.Группировка КАК Группировка, ВТ_ОстаточнаяНагрузка.Склад КАК Склад, ВТ_ОстаточнаяНагрузка.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ОстаточнаяНагрузка.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ПОМЕСТИТЬ ВТ_ИтоговыйЗапрос ИЗ ВТ_ОстаточнаяНагрузка КАК ВТ_ОстаточнаяНагрузка
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_НеРаспределено.Группировка, ВТ_НеРаспределено.Склад, ВТ_НеРаспределено.КоличествоМ2Потолков, ВТ_НеРаспределено.ЗаказНаПроизовдство ИЗ ВТ_НеРаспределено КАК ВТ_НеРаспределено
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_Сегодня.Группировка, ВТ_Сегодня.Склад, ВТ_Сегодня.КоличествоМ2Потолков, ВТ_Сегодня.ЗаказНаПроизовдство ИЗ ВТ_Сегодня КАК ВТ_Сегодня
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_Завтра.Группировка, ВТ_Завтра.Склад, ВТ_Завтра.КоличествоМ2Потолков, ВТ_Завтра.ЗаказНаПроизовдство ИЗ ВТ_Завтра КАК ВТ_Завтра
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_Послезавтра.Группировка, ВТ_Послезавтра.Склад, ВТ_Послезавтра.КоличествоМ2Потолков, ВТ_Послезавтра.ЗаказНаПроизовдство ИЗ ВТ_Послезавтра КАК ВТ_Послезавтра
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ВТ_Будущие.Группировка, ВТ_Будущие.Склад, ВТ_Будущие.КоличествоМ2Потолков, ВТ_Будущие.ЗаказНаПроизовдство ИЗ ВТ_Будущие КАК ВТ_Будущие ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВТ_ГруппировкиИСклады.Порядок КАК Порядок, ВТ_ГруппировкиИСклады.Группировка КАК Группировка, ВТ_ГруппировкиИСклады.Склад КАК Склад, ВТ_ИтоговыйЗапрос.КоличествоМ2Потолков КАК КоличествоМ2Потолков, ВТ_ИтоговыйЗапрос.ЗаказНаПроизовдство КАК ЗаказНаПроизовдство ИЗ ВТ_ГруппировкиИСклады КАК ВТ_ГруппировкиИСклады ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ИтоговыйЗапрос КАК ВТ_ИтоговыйЗапрос ПО ВТ_ГруппировкиИСклады.Группировка = ВТ_ИтоговыйЗапрос.Группировка И ВТ_ГруппировкиИСклады.Склад = ВТ_ИтоговыйЗапрос.Склад
УПОРЯДОЧИТЬ ПО Порядок
